src='''from collections import Counter


def transform(grid):
    """Continue a repeated horizontal pattern, marking newly inferred cells with 1."""
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(original), len(original[0])
    background = Counter(cell for row in original for cell in row).most_common(1)[0][0]

    # Find contiguous bands of rows that contain foreground cells.
    active = [any(cell != background for cell in row) for row in original]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        end = r
        while end < h and active[end]:
            end += 1
        bands.append((r, end))
        r = end

    # Repeated bands share a left-to-right sequence. Align the start of the
    # upper band with the lower band at the offset that gives the longest
    # exact overlap, then mark the continuation in the shorter copy.
    for ai, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[ai + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            height = a1 - a0
            candidates = []
            for dx in range(w):
                lengths = []
                for offset in range(height):
                    a = original[a0 + offset]
                    b = original[b0 + offset]
                    length = 0
                    while length < w and length + dx < w and a[length] == b[length + dx]:
                        length += 1
                    lengths.append(length)
                candidates.append((sum(lengths), -dx, dx, lengths))
            _, _, dx, lengths = max(candidates)
            if min(lengths) < max(3, int(0.25 * w)):
                continue

            if dx == 0:
                # Same alignment: extend whichever row has the longer pattern.
                for offset, length in enumerate(lengths):
                    a = original[a0 + offset]
                    b = original[b0 + offset]
                    for col in range(length, w):
                        if a[col] != background and b[col] == background:
                            out[b0 + offset][col] = 1
                        elif b[col] != background and a[col] == background:
                            out[a0 + offset][col] = 1
            else:
                # The lower copy is shifted right; continue the upper sequence.
                for offset, length in enumerate(lengths):
                    a = original[a0 + offset]
                    for col in range(length, w):
                        dest = col + dx
                        if dest < w and a[col] != background and original[b0 + offset][dest] == background:
                            out[b0 + offset][dest] = 1
    return out
